type UseTogglePinDiscussionOptions = {
  mutationConfig?: MutationConfig<typeof togglePinDiscussion>;
};

export const useTogglePinDiscussion = ({
  mutationConfig,
}: UseTogglePinDiscussionOptions = {}) => {
  const queryClient = useQueryClient();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (data, ...args) => {
      queryClient.refetchQueries({
        queryKey: getDiscussionQueryOptions(data.id).queryKey,
